  XW += x[20] * 7.5087000000000003e+01;    // C3H6OOH2-1
  XW += x[21] * 2.7045999999999999e+01;    // C2H3
  XW += x[22] * 5.7072000000000003e+01;    // C2H5CO
  XW += x[23] * 1.0708500000000001e+02;    // C3H6OOH1-2O2
  XW += x[24] * 3.3006000000000000e+01;    // HO2
  XW += x[25] * 2.6037999999999997e+01;    // C2H2
