  XW += x[34] * 7.5087000000000003e+01;    // C3H6OOH2-2
  XW += x[35] * 2.8009999999999998e+01;    // CO
  XW += x[36] * 4.3045000000000002e+01;    // CH3CO
  XW += x[37] * 7.7058999999999997e+01;    // CH2OCH2O2H
  XW += x[38] * 7.6094999999999999e+01;    // NC3H7O2H
