  XW += x[18] * 2.8053999999999998e+01;  // C2H4
  XW += x[19] * 5.8080000000000005e+01;  // C2H5CHO
  XW += x[20] * 7.5087000000000003e+01;  // C3H6OOH2-1
  XW += x[21] * 2.7045999999999999e+01;  // C2H3
  XW += x[22] * 5.7072000000000003e+01;  // C2H5CO
  XW += x[23] * 1.0708500000000001e+02;  // C3H6OOH1-2O2
  XW += x[24] * 3.3006000000000000e+01;  // HO2
  XW += x[25] * 2.6037999999999997e+01;  // C2H2
  XW += x[26] * 4.6069000000000003e+01;  // CH3OCH3
  XW += x[27] * 1.0708500000000001e+02;  // C3H6OOH1-3O2
  XW += x[28] * 3.4014000000000003e+01;  // H2O2
  XW += x[29] * 2.5029999999999998e+01;  // C2H
  XW += x[30] * 4.5061000000000000e+01;  // CH3OCH2
  XW += x[31] * 1.0708500000000001e+02;  // C3H6OOH2-1O2
  XW += x[32] * 4.4052999999999997e+01;  // CH3CHO
  XW += x[33] * 7.7058999999999997e+01;  // CH3OCH2O2
  XW += x[34] * 7.5087000000000003e+01;  // C3H6OOH2-2
  XW += x[35] * 2.8009999999999998e+01;  // CO
  XW += x[36] * 4.3045000000000002e+01;  // CH3CO
  XW += x[37] * 7.7058999999999997e+01;  // CH2OCH2O2H
  XW += x[38] * 7.6094999999999999e+01;  // NC3H7O2H
  XW += x[39] * 4.4009000000000000e+01;  // CO2
  XW += x[40] * 4.3045000000000002e+01;  // CH2CHO
  XW += x[41] * 7.8067000000000007e+01;  // CH3OCH2O2H
  XW += x[42] * 7.6094999999999999e+01;  // IC3H7O2H
  XW += x[43] * 3.0026000000000000e+01;  // CH2O
  XW += x[44] * 4.2036999999999999e+01;  // CH2CO
  XW += x[45] * 6.1060000000000002e+01;  // CH3OCH2O
  XW += x[46] * 7.5087000000000003e+01;  // NC3H7O2
  XW += x[47] * 2.9018000000000001e+01;  // HCO
  XW += x[48] * 4.1028999999999996e+01;  // HCCO
  XW += x[49] * 1.0905700000000000e+02;  // O2CH2OCH2O2H
  XW += x[50] * 7.5087000000000003e+01;  // IC3H7O2
  XW += x[51] * 6.2024000000000001e+01;  // HO2CHO
  XW += x[52] * 4.2036999999999999e+01;  // HCCOH
