  XW += x[60] * 7.5043000000000006e+01;  // CH3CO3
  XW += x[61] * 7.5043000000000006e+01;  // HOCH2OCO
  XW += x[62] * 5.8080000000000005e+01;  // C3H6O1-2
  XW += x[63] * 4.5016999999999996e+01;  // OCHO
  XW += x[64] * 5.9043999999999997e+01;  // CH3CO2
  XW += x[65] * 6.0052000000000000e+01;  // CH3OCHO
