  XW += x[67] * 6.4039999999999992e+01;  // HOCH2O2H
  XW += x[68] * 4.6069000000000003e+01;  // C2H5OH
  XW += x[69] * 5.9043999999999997e+01;  // CH3OCO
  XW += x[70] * 9.0078000000000003e+01;  // C3KET12
  XW += x[71] * 6.3031999999999996e+01;  // HOCH2O2
  XW += x[72] * 4.5061000000000000e+01;  // C2H5O
  XW += x[73] * 5.9043999999999997e+01;  // CH2OCHO
  XW += x[74] * 9.0078000000000003e+01;  // C3KET13
  XW += x[75] * 6.3031999999999996e+01;  // OCH2O2H
  XW += x[76] * 4.5061000000000000e+01;  // PC2H4OH
  XW += x[77] * 9.0078000000000003e+01;  // C3KET21
  XW += x[78] * 4.7033000000000001e+01;  // HOCH2O
  XW += x[79] * 4.5061000000000000e+01;  // SC2H4OH
